import {validateSurfaceDetails} from './building-surface-details.js?v=theme-park-1';
import {validateFloorPaint,clearColumnFloorPaint} from './building-floor-paint.js?v=theme-park-1';
import {mountBuildingVoxelEditor} from './building-voxel-editor.js?v=theme-park-1';
import {blocksToVoxels} from './building-voxels.js?v=theme-park-1';
import {buildingShapeCells,applyBuildingShape} from './building-shapes.js?v=theme-park-1';
import {validateBuildingMaterials,BUILDING_MATERIALS,SURFACE_NAMES,exposedSurface,paintBuildingSurface} from './building-materials.js?v=theme-park-1';
import {towerToBlocks,paintBuildingBlock} from './building-blocks.js?v=theme-park-1';
export function mountBuildingBlockEditor(root,{get,set,view=()=>{}}){
 root.innerHTML=`<label>Construction method<select id="blockMode"><option value="tower">Tower parameters</option><option value="blocks">Paint a block layout</option><option value="voxels">Build independent layers</option></select></label><section id="blockWorkspace" hidden><p>Paint a height onto the footprint. Use 0 to erase. Drag across squares, or use arrow keys and Enter/Space. The footprint stays north-up while the preview rotates. Heights are floors. Line and plane tools preview until release; hold Shift on release or press Escape to cancel. Keyboard: Shift+Enter starts a shape, arrows extend it, Enter places it.</p><div class="block-editor-controls"><label>Editing tool<select id="blockTool"><option value="height">Height brush</option><option value="paint">Surface paintbrush</option><option value="fill">Fill connected surfaces</option></select></label><label>Height application<select id="blockShape"><option value="brush">Freehand</option><option value="line">Line</option><option value="plane">Plane</option></select></label><label>Surface<select id="blockSide">${SURFACE_NAMES.map((name,i)=>`<option value="${i}">${name}</option>`).join('')}</select></label><label>Material<select id="blockMaterial">${BUILDING_MATERIALS.map((name,i)=>`<option value="${i}">${name}</option>`).join('')}</select></label><label>Height brush (0–24)<input id="blockBrush" type="number" min="0" max="24" step="1" value="8"></label><button id="blockUndo">Undo layout edit</button><button id="blockRedo">Redo layout edit</button><button id="blockFromTower">Use tower footprint</button><button id="blockClear">Clear footprint</button></div><div id="blockGrid" role="grid" aria-label="Building footprint, north at top" aria-rowcount="10" aria-colcount="10">${Array.from({length:10},(_,y)=>`<div role="row">${Array.from({length:10},(_,x)=>`<button type="button" role="gridcell" data-block-index="${y*10+x}" tabindex="${x===0&&y===0?0:-1}"></button>`).join('')}</div>`).join('')}</div><p>Surface tools paint the selected side of each column. Fill joins touching surfaces with the same height and material; walls stay on one plane. Hidden walls cannot be painted.</p><p id="blockStatus" role="status"></p></section><div id="voxelEditor"></div>`;
 const $=id=>root.querySelector('#'+id),grid=$('blockGrid'),cells=[...grid.querySelectorAll('[data-block-index]')],history=[],future=[];let voxelEditor,voxelMemory=null,shape=null,memory=null,active=0,stroke=null,strokeSaved=false;
 const isBlocks=()=>Array.isArray(get().blocks),snapshot=()=>({blocks:[...get().blocks],surfaceDetails:get().surfaceDetails,surfacePaint:get().surfacePaint,...(get().materials?{materials:[...get().materials]}:{})});
 function refresh(){const blocks=get().blocks; voxelEditor?.refresh();$('blockMode').value=get().voxels?'voxels':blocks?'blocks':'tower';$('blockWorkspace').hidden=!blocks;for(const id of ['designFloors','designWidth','designDepth','designRoof'])document.getElementById(id).disabled=!!blocks||!!get().voxels;$('blockUndo').disabled=!history.length;$('blockRedo').disabled=!future.length;const painting=$('blockTool').value!=='height',side=Number($('blockSide').value);$('blockBrush').disabled=painting;$('blockShape').disabled=painting;$('blockSide').disabled=!painting;$('blockMaterial').disabled=!painting;if(!blocks)return;cells.forEach((cell,i)=>{const h=blocks[i],material=get().materials?.[i*5+side]||0,exposed=exposedSurface(blocks,i,side);cell.textContent=painting?(exposed?['F','B','S','G','T'][material]:'·'):(h||'·');cell.setAttribute('aria-label',`Column ${i%10+1}, row ${Math.floor(i/10)+1}: ${h} floors${painting?`, ${SURFACE_NAMES[side]}: ${exposed?BUILDING_MATERIALS[material]:'not exposed'}`:''}`);cell.tabIndex=i===active?0:-1;cell.style.boxShadow=shape&&buildingShapeCells(shape.kind,shape.start,shape.end).includes(i)?'inset 0 0 0 3px #d79b00':'';cell.style.background=painting?(exposed?['#b6c4bd','#aa6750','#d4c5aa','#3c6b79','#7a5960'][material]:'#eef1ef'):`hsl(172 20% ${94-h*1.7}%)`;cell.style.color=painting?(exposed&&[1,3,4].includes(material)?'#fff':'#17382f'):(h>14?'#fff':'#17382f');});$('blockStatus').textContent=blocks.some(h=>h)?`${blocks.filter(h=>h).length} occupied squares · tallest section ${Math.max(...blocks)} floors. Changes are a draft until applied.`:'Empty footprint. Paint at least one square before applying or exporting.';}
 function remember(){future.length=0;history.push(snapshot());if(history.length>20)history.shift();}
 function replace(blocks,save=true,materials=get().materials,surfacePaint=get().surfacePaint,surfaceDetails=get().surfaceDetails){if(save)remember();const next={...get(),blocks};if(surfaceDetails)next.surfaceDetails=surfaceDetails;else delete next.surfaceDetails;if(surfacePaint)next.surfacePaint=surfacePaint;else delete next.surfacePaint;if(materials)next.materials=[...materials];else delete next.materials;set(next);memory=snapshot();refresh();}
 function brush(){const n=Number($('blockBrush').value);if($('blockBrush').value.trim()===''||!Number.isInteger(n)||n<0||n>24){$('blockStatus').textContent='Choose a whole height from 0 to 24.';return null;}return n;}
 function cancelShape(){shape=null;stroke=null;strokeSaved=false;refresh();}
 function beginShape(index){const height=brush();if(height===null)return false;shape={kind:$('blockShape').value,start:index,end:index,height};refresh();return true;}
 function finishShape(cancel=false){const selected=shape;shape=null;stroke=null;if(selected&&!cancel){const next=applyBuildingShape(get().blocks,selected.kind,selected.start,selected.end,selected.height);if(next.some((h,i)=>h!==get().blocks[i]))replace(next);}refresh();}
 function paint(index,drag=false){if(!isBlocks())return;const tool=$('blockTool').value;let next,materials=get().materials,touched=[];if(tool==='height'){const height=brush();if(height===null||get().blocks[index]===height)return;next=paintBuildingBlock(get().blocks,index%10,Math.floor(index/10),height);}else{const side=Number($('blockSide').value);if(!exposedSurface(get().blocks,index,side))return;materials=paintBuildingSurface(get().blocks,materials,index,side,Number($('blockMaterial').value),tool==='fill',touched);if(materials.every((v,i)=>v===(get().materials?.[i]||0))&&!get().surfacePaint)return;next=[...get().blocks];}if(!drag||!strokeSaved){remember();strokeSaved=true;}replace(next,false,materials,tool==='height'?get().surfacePaint:clearColumnFloorPaint(get().surfacePaint,touched));}
 $('blockMode').onchange=()=>{shape=null;stroke=null;future.length=0;const mode=$('blockMode').value,current=get();if(current.voxels)voxelMemory={blockGeometry:current.blockGeometry,voxels:[...current.voxels],surfaceDetails:current.surfaceDetails,surfacePaint:current.surfacePaint,...(current.materials?{materials:[...current.materials]}:{})};if(current.blocks)memory=snapshot();const next={...current};delete next.blocks;delete next.voxels;delete next.blockGeometry;delete next.surfaceDetails;delete next.materials;delete next.surfacePaint;if(mode==='voxels')Object.assign(next,voxelMemory?structuredClone(voxelMemory):{voxels:blocksToVoxels(current.blocks||towerToBlocks(current)),surfaceDetails:current.surfaceDetails,surfacePaint:current.surfacePaint,...(current.materials?{materials:[...current.materials]}:{})});if(mode==='blocks')Object.assign(next,memory?structuredClone(memory):{blocks:towerToBlocks(current)});set(next);history.length=0;voxelEditor.reset();refresh();};
 $('blockUndo').onclick=()=>{cancelShape();if(history.length){future.push(snapshot());const old=history.pop();replace(old.blocks,false,old.materials||null,old.surfacePaint??null,old.surfaceDetails??null);}};$('blockRedo').onclick=()=>{cancelShape();if(future.length){history.push(snapshot());const next=future.pop();replace(next.blocks,false,next.materials||null,next.surfacePaint??null,next.surfaceDetails??null);}};$('blockClear').onclick=()=>{cancelShape();replace(Array(100).fill(0),true,null,null,null);};$('blockFromTower').onclick=()=>{cancelShape();replace(towerToBlocks(get()),true,null,null,null);};
 for(const id of ['blockTool','blockSide','blockMaterial','blockShape'])$(id).onchange=cancelShape;
 grid.onpointerdown=event=>{if(event.button!==0)return;const cell=event.target.closest('[data-block-index]');if(!cell)return;event.preventDefault();stroke=event.pointerId;strokeSaved=false;active=Number(cell.dataset.blockIndex);cell.focus({preventScroll:true});grid.setPointerCapture(event.pointerId);if($('blockTool').value==='height'&&$('blockShape').value!=='brush')beginShape(active);else paint(active,true);refresh();};
 grid.onpointermove=event=>{if(stroke!==event.pointerId)return;const cell=document.elementFromPoint(event.clientX,event.clientY)?.closest('[data-block-index]');if(cell&&grid.contains(cell)){const index=Number(cell.dataset.blockIndex);if(shape){shape.end=index;refresh();}else paint(index,true);}};
 grid.onpointerup=event=>{if(shape)finishShape(event.shiftKey);stroke=null;strokeSaved=false;};grid.onpointercancel=()=>{if(shape)finishShape(true);stroke=null;strokeSaved=false;};
 grid.onclick=event=>{if(event.detail!==0)return;const cell=event.target.closest('[data-block-index]');if(cell){active=Number(cell.dataset.blockIndex);paint(active);}};
 grid.onkeydown=event=>{if(event.key==='Escape'&&shape){event.preventDefault();cancelShape();return;}if(event.key==='Enter'&&$('blockTool').value==='height'&&$('blockShape').value!=='brush'&&(event.shiftKey||shape)){event.preventDefault();if(shape)finishShape();else beginShape(active);return;}const moves={ArrowLeft:-1,ArrowRight:1,ArrowUp:-10,ArrowDown:10};if(!(event.key in moves))return;event.preventDefault();const cell=event.target.closest('[data-block-index]');if(cell)active=Number(cell.dataset.blockIndex);const next=active+moves[event.key];if(next<0||next>=100||event.key==='ArrowLeft'&&active%10===0||event.key==='ArrowRight'&&active%10===9)return;active=next;if(shape)shape.end=active;refresh();cells[active].focus();};
 voxelEditor=mountBuildingVoxelEditor($('voxelEditor'),{get,set,view});
 return {applyDetails(details){const next=validateSurfaceDetails(details);if(get().voxels)return voxelEditor.applyDetails(next);if(!isBlocks()||next===get().surfaceDetails)return;replace(get().blocks,true,get().materials,get().surfacePaint,next);},applyFloorPaint(paint){const next=validateFloorPaint(paint);if(get().voxels)return voxelEditor.applyFloorPaint(next);if(!isBlocks()||next===get().surfacePaint)return;replace(get().blocks,true,get().materials,next);},applyMaterials(materials){const next=validateBuildingMaterials(materials);if(get().voxels)return voxelEditor.applyMaterials(next);if(!isBlocks()||next.every((v,i)=>v===(get().materials?.[i]||0)))return;replace(get().blocks,true,next,clearColumnFloorPaint(get().surfacePaint,next.map((v,i)=>i).filter(i=>next[i]!==(get().materials?.[i]||0))));},selection:()=>voxelEditor.selection(),reset(){voxelMemory=get().voxels?{blockGeometry:get().blockGeometry,voxels:[...get().voxels],surfaceDetails:get().surfaceDetails,surfacePaint:get().surfacePaint,...(get().materials?{materials:[...get().materials]}:{})}:null;voxelEditor.reset();shape=null;future.length=0;history.length=0;memory=get().blocks?snapshot():null;stroke=null;refresh();},refresh};
}
